import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../app_config.dart';
import '../../notifications/show_flush_bar.dart';
import '../../utilities/app_data_wipe.dart';
import '../../utilities/logger.dart';
import '../../utilities/text_styles.dart';
import '../../widgets/app_icon.dart';
import '../../widgets/custom_buttons/app_bar_icon_button.dart';
import '../../widgets/desktop/desktop_app_bar.dart';
import '../../widgets/desktop/desktop_scaffold.dart';
import '../../widgets/desktop/primary_button.dart';
import '../../widgets/desktop/secondary_button.dart';

class DeletePasswordWarningView extends ConsumerStatefulWidget {
  const DeletePasswordWarningView({super.key, required this.shouldCreateNew});

  static const String routeName = "/deletePasswordWarning";

  final bool shouldCreateNew;

  @override
  ConsumerState<DeletePasswordWarningView> createState() =>
      _ForgotPasswordDesktopViewState();
}

class _ForgotPasswordDesktopViewState
    extends ConsumerState<DeletePasswordWarningView> {
  bool _deleteInProgress = false;

  @override
  Widget build(BuildContext context) {
    return DesktopScaffold(
      appBar: DesktopAppBar(
        leading: AppBarBackButton(
          onPressed: () async {
            if (mounted && !_deleteInProgress) {
              Navigator.of(context).pop();
            }
          },
        ),
        isCompactHeight: false,
      ),
      body: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          SizedBox(
            width: 480,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                const AppIcon(width: 100),
                const SizedBox(height: 42),
                Text("Warning!", style: STextStyles.desktopH1(context)),
                const SizedBox(height: 24),
                SizedBox(
                  width: 480,
                  child: RichText(
                    textAlign: TextAlign.center,
                    text: TextSpan(
                      children: [
                        TextSpan(
                          text: "To ",
                          style: STextStyles.desktopTextSmall(context),
                        ),
                        TextSpan(
                          text: widget.shouldCreateNew
                              ? "create a new ${AppConfig.prefix}"
                              : "restore from backup",
                          style: STextStyles.desktopTextSmallBold(context),
                        ),
                        TextSpan(
                          text: ", we need to ",
                          style: STextStyles.desktopTextSmall(context),
                        ),
                        TextSpan(
                          text: "delete your old wallets",
                          style: STextStyles.desktopTextSmallBold(context),
                        ),
                        TextSpan(
                          text:
                              ". Make sure you have the recovery phrase of each "
                              "one: without it, its funds are lost.\n\n"
                              "${AppConfig.appName} closes when it's done. Open "
                              "it again to "
                              "${widget.shouldCreateNew ? "start over" : "restore your backup"}.",
                          style: STextStyles.desktopTextSmall(context),
                        ),
                      ],
                    ),
                  ),
                ),
                const SizedBox(height: 48),
                PrimaryButton(
                  label: "Delete and close",
                  enabled: !_deleteInProgress,
                  onPressed: () async {
                    if (_deleteInProgress) return;
                    setState(() => _deleteInProgress = true);
                    try {
                      await AppDataWipe.wipeDesktopAndExit();
                    } catch (e, s) {
                      Logging.instance.e(
                        "Deleting the app data failed",
                        error: e,
                        stackTrace: s,
                      );
                      if (!mounted) return;
                      unawaited(
                        showFloatingFlushBar(
                          type: FlushBarType.warning,
                          message: "Deleting failed: $e",
                          context: context,
                        ),
                      );
                      setState(() => _deleteInProgress = false);
                    }
                  },
                ),
                const SizedBox(height: 24),
                SecondaryButton(
                  label: "Take me back!",
                  enabled: !_deleteInProgress,
                  onPressed: () {
                    Navigator.of(context).pop();
                  },
                ),
                const SizedBox(height: kDesktopAppBarHeight),
              ],
            ),
          ),
        ],
      ),
    );
  }
}
